s05-membership-index-replay	1	CALL domain-versioned-edit {"fixture":"membership_http","initial_membership":"confirmed_absent","create_if_match":"\"\"","lost_answer_on_empty_put":true,"retry_old_index_and_key":true}	{"create_status":200,"stale_absent_condition_status":412,"stale_field":"/index","stale_revision_in_body":false,"delete_status":200,"delete_index":"","membership_row_absent":true,"replay_status":200,"replay_body_equal":true,"etag_in_responses":false,"duplicate_target_writes":0}
