s08-folder-versioned-lifecycle	1	CALL domain-versioned-edit {"fixture":"folder_http_lifecycle","operations":["create","replay_create","rename_stale","rename_current","delete_stale","delete_current"],"replay_create_old_condition":true}	{"statuses":[201,201,412,200,412,200],"create_replay_same_id":true,"create_replay_body_equal":true,"create_replay_etag_equal":true,"stale_target_writes":0,"folder_row_is_tombstone":true,"folder_revision_after":3,"delete_etag_is_tombstone_index":true}
"

s05-global-role-safe-spread	1	CALL domain-role-http { ixture":"role_to_member","scopes":["*","folder:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"],"steps":["write_lines_http","spread","carry_to_member","may_at_member"]}	{"statuses":[200,200],"spread_role_scopes":["*","folder:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"],"member_allows":[true,true],"invalid_role_grant_writes":0}
s06-global-role-labels-unit-refused	1	CALL domain-role-http {"fixture":"role_to_member","scopes":["labels:east","unit:testsub/u1"],"steps":["write_lines_http","seed_unreadable_legacy_role","spread","trusted_may_known_form"]}	{"statuses":[400,400],"errors":["bad line","bad line"],"door_target_writes":0,"invalid_role_grant_writes":0,"trusted_may_exit":2}
s07-supervision-http-lifecycle	1	CALL domain-role-http {"fixture":"supervision_http","role":"R","supervisor":"S","sub":"exp","operations":["create_supervisor","create_role_with_supervision","read_role","put_title_only","replace_with_self","clear_with_empty_object","read_role"]}	{"create_statuses":[201,201],"created_supervision":{"exp":"S"},"omitted_preserves":true,"replace_status":200,"replaced_supervision":{"exp":"R"},"clear_status":200,"supervision_absent_after_clear":true,"responses_match_closed_role_schema":true}
s08-supervision-reference-guards	1	CALL domain-role-http {"fixture":"supervision_guards","operations":["unknown_supervisor","delete_referenced_supervisor","delete_self_referenced_role","change_builtin_admin","unconfirmed_supervisor"]}	{"statuses":[400,409,200,409,503],"errors":["unknown role","role referenced","","builtin","unavailable"],"writes_on_refusals":0,"foreign_reference_preserved":true}
s09-supervision-batch-final-snapshot	1	CALL domain-role-http {"fixture":"supervision_batch","operations":["create_role_and_supervisor_in_same_batch","clear_reference_and_delete_supervisor_in_same_batch","null_supervision","unknown_supervisor"]}	{"statuses":[200,200,400,400],"written":[2,2,0,0],"partial_batch_writes":0,"guarded_final_snapshot":true}
s10-login-fixed-origin	1	CALL domain-person-login {"fixture":"ordinary_person_login","credential_at":100,"verification_returns_at":101}	{"status":200,"iat":100,"exp":1000,"until":1000,"claims_verified_by_real_signature":true}
s11-login-delete-recreate-delayed	1	CALL domain-person-login {"fixture":"delayed_old_password","credential_at":0,"delete_at":1,"recreate_at":962,"old_verification_returns_at":964,"new_login_at":965}	{"old_status":401,"old_error":"refused","old_token_issued":false,"new_status":200,"new_iat":965,"new_exp":1865,"old_password_authenticates_new_person":false}
"

- {$ref: '#/components/parameters/XW2CClient'}
- {$ref: '#/components/parameters/RepeatKey'}
