        headers:
          ETag: {$ref: '#/components/headers/ETag'}
        content:
          application/json:
            schema:
              type: object
              required: [role, revision]
              additionalProperties: false
              properties:
                role: {$ref: '#/components/schemas/PersonName'}
                revision: {type: integer, minimum: 1}
      '412': {$ref: '#/components/responses/RevisionMoved'}
      '400': {$ref: '#/components/responses/Refused'}
      '401': {$ref: '#/components/responses/Denied'}
      '403': {$ref: '#/components/responses/Denied'}
