/domain/folders:
  post:
    operationId: folderCreate
    summary: New domain folder (P/08.5 N1.8); If-Match is ignored at creation.
    parameters:
      - {$ref: '#/components/parameters/XW2CClient'}
      - {$ref: '#/components/parameters/RepeatKey'}
    requestBody:
      required: true
      content:
        application/json:
          schema:
            type: object
            required: [name]
            additionalProperties: false
            properties:
              name: {$ref: '#/components/schemas/DomainFolderName'}
              parent: {type: string, pattern: '^(?:(?:[0-9a-f]{32})?)$', default: ''}
    responses:
      '201':
        description: The new folder; a repeat with the same key returns the saved response.
        headers:
          ETag: {$ref: '#/components/headers/ETag'}
        content:
          application/json:
            schema: {$ref: '#/components/schemas/DomainFolderView'}
      '412': {$ref: '#/components/responses/DomainFolderRefused'}
      '400': {$ref: '#/components/responses/DomainFolderRefused'}
      '401': {$ref: '#/components/responses/Denied'}
      '403': {$ref: '#/components/responses/Denied'}
      '404': {$ref: '#/components/responses/DomainFolderRefused'}
      '408': {$ref: '#/components/responses/BodyRefused'}
      '409': {$ref: '#/components/responses/DomainFolderRefused'}
      '413': {$ref: '#/components/responses/BodyRefused'}
      '422': {$ref: '#/components/responses/KeyReused'}
      '503': {$ref: '#/components/responses/StandbyFrozenOrUnavailable'}

'200':
  description: Folder after the write.
  headers:
    ETag: {$ref: '#/components/headers/ETag'}
  content:
    application/json:
      schema: {$ref: '#/components/schemas/DomainFolderView'}
'412': {$ref: '#/components/responses/DomainFolderConditionRefused'}
'400': {$ref: '#/components/responses/DomainFolderRefused'}
'401': {$ref: '#/components/responses/Denied'}
'403': {$ref: '#/components/responses/Denied'}
'404': {$ref: '#/components/responses/DomainFolderRefused'}
'408': {$ref: '#/components/responses/BodyRefused'}
'409': {$ref: '#/components/responses/DomainFolderRefused'}
'413': {$ref: '#/components/responses/BodyRefused'}
'422': {$ref: '#/components/responses/KeyReused'}
'503': {$ref: '#/components/responses/StandbyFrozenOrUnavailable'}

summary: Write the domain folder tombstone; the row and its index remain.
parameters:
  - {$ref: '#/components/parameters/XW2CClient'}
  - {$ref: '#/components/parameters/RepeatKey'}
  - {$ref: '#/components/parameters/IfMatch'}

'200':
  description: Tombstone written; ETag is its result row index.
  headers:
    ETag: {$ref: '#/components/headers/ETag'}
  content:
    application/json:
      schema:
        type: object
        required: [deleted]
        additionalProperties: false
        properties:
          deleted: {type: string, pattern: '^(?:[0-9a-f]{32})$'}
'412': {$ref: '#/components/responses/DomainFolderConditionRefused'}
'400': {$ref: '#/components/responses/DomainFolderRefused'}
'401': {$ref: '#/components/responses/Denied'}
'403': {$ref: '#/components/responses/Denied'}
'404': {$ref: '#/components/responses/DomainFolderRefused'}
'408': {$ref: '#/components/responses/BodyRefused'}
'409': {$ref: '#/components/responses/DomainFolderRefused'}
'413': {$ref: '#/components/responses/BodyRefused'}
'422': {$ref: '#/components/responses/KeyReused'}
'503': {$ref: '#/components/responses/StandbyFrozenOrUnavailable'}

'200':
  description: Current folders and membership row index; an empty list deletes it and returns index empty. No ETag.
  content:
    application/json:
      schema: {$ref: '#/components/schemas/DomainMembershipView'}
'412': {$ref: '#/components/responses/IndexMoved'}
'400': {$ref: '#/components/responses/DomainFolderRefused'}
'401': {$ref: '#/components/responses/Denied'}
'403': {$ref: '#/components/responses/Denied'}
'404': {$ref: '#/components/responses/DomainFolderRefused'}
'408': {$ref: '#/components/responses/BodyRefused'}
'409': {$ref: '#/components/responses/DomainFolderRefused'}
'413': {$ref: '#/components/responses/BodyRefused'}
'422': {$ref: '#/components/responses/KeyReused'}
'503': {$ref: '#/components/responses/StandbyFrozenOrUnavailable'}

allOf:
  - if:
      required: [kind, op]
      properties:
        kind: {const: role}
        op: {const: put}
    then:
      properties:
        fields: {$ref: '#/components/schemas/RolePutFields'}

RoleSupervision:
  type: object
  description: 'Subsystem to supervisor role. POST omission/{} means none; PUT omission preserves, {} clears, a nonempty object replaces. Null is invalid. Self-reference is allowed; other roles require existence/version guards; builtin admin refuses changes.'
  propertyNames: {$ref: '#/components/schemas/SubName'}
  additionalProperties: {$ref: '#/components/schemas/PersonName'}
RolePutFields:
  type: object
  additionalProperties: false
  description: 'Role fields of a batch put; same supervision and reference guards over the final snapshot as ordinary role POST/PUT. No name field: BatchWrite.name supplies it.'
  properties:
    title: {type: string, maxLength: 200}
    comment: {type: string, maxLength: 2000}
    assigned: {type: array, items: {$ref: '#/components/schemas/RoleAssigned'}}
    supervision: {$ref: '#/components/schemas/RoleSupervision'}
RestoreBusyBody:
  type: object
  required: [error, detail]
  additionalProperties: false
  properties:
    error: {const: refused}
    detail: {const: 'a move is under way here already: seconds, not minutes'}
GlobalRoleLine:
  type: object
  required: [cap, scope, until]
  additionalProperties: false
  description: 'Whole-domain role line: labels and unit scopes are forbidden, as on a role grant line (P/08.4 N1.3a).'
  properties:
    cap: {$ref: '#/components/schemas/LineCap'}
    sub: {$ref: '#/components/schemas/SubName'}
    scope: {type: string, pattern: '^(?:\*|folder:[0-9a-f]{32})$'}
    until: {type: number, minimum: 0}
DomainFolderName:
  type: string
  minLength: 1
  x-max-bytes: 255
  description: 'Nonempty, at most FOLDER_NAME_MAX (255) UTF-8 bytes; the ordinary procedure checks the byte bound (P/06.8 N1.1).'
DomainFolderView:
  type: object
  required: [id, name, parent, revision, index]
  additionalProperties: false
  properties:
    id: {type: string, pattern: '^(?:[0-9a-f]{32})$'}
    name: {$ref: '#/components/schemas/DomainFolderName'}
    parent: {type: string, pattern: '^(?:(?:[0-9a-f]{32})?)$'}
    revision: {type: integer, minimum: 0}
    index: {type: string, pattern: '^(?:0|[1-9][0-9]{0,19})$'}
DomainMembershipView:
  type: object
  required: [folders, index]
  additionalProperties: false
  description: 'No synthetic revision. Empty folders remove the row; its confirmed absent index is the empty string.'
  properties:
    folders:
      type: array
      uniqueItems: true
      items: {type: string, pattern: '^(?:[0-9a-f]{32})$'}
    index: {type: string, pattern: '^(?:(?:0|[1-9][0-9]{0,19})?)$'}
IndexMoved:
  type: object
  required: [error, field, index]
  additionalProperties: false
  properties:
    error: {const: revision moved}
    field: {const: /index}
    index: {type: string, pattern: '^(?:(?:0|[1-9][0-9]{0,19})?)$'}
    detail: {type: string}
    row: {$ref: '#/components/schemas/DomainMembershipView'}
